package io.github.flipendo.spike;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.widget.*;import java.io.*;import java.util.*;
public final class HDPackActivity extends Activity {
 File root;boolean hp2,busy;TextView status;Button install,remove;Thread worker;
 public void onCreate(Bundle state){super.onCreate(state);hp2=getIntent().getBooleanExtra("hp2",false);String path=getIntent().getStringExtra("directory");if(path==null){finish();return;}root=new File(path);if(GameFiles.find(hp2,root,0)==null){finish();return;}
 LinearLayout col=new LinearLayout(this);col.setOrientation(1);col.setPadding(35,25,35,25);col.setBackgroundColor(0xff101b22);TextView title=new TextView(this);title.setText((hp2?"Chamber of Secrets":"Philosopher’s Stone")+" — HD textures");title.setTextColor(0xffecdcb6);title.setTextSize(23);col.addView(title);
 TextView hint=new TextView(this);hint.setText("HD modules are separate optional downloads from the project repository. Import one or more module ZIPs here. Successful installation enables HD for this game. Only packs marked for this game are installed. Install fewer modules if memory is limited. Original game packages and saves are preserved. Keep this screen open during installation.");hint.setTextColor(0xffecdcb6);col.addView(hint);status=new TextView(this);status.setTextColor(0xffecdcb6);col.addView(status);install=new Button(this);install.setText("Install HD pack ZIPs");install.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,78);});col.addView(install);remove=new Button(this);remove.setText("Remove installed HD overrides");remove.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("Remove HD textures for this game? Original textures and saves stay available.").setPositiveButton("Remove",(d,w)->work(()->{HDPackInstaller.remove(root);BundledHD.disable(root);getSharedPreferences("setup",MODE_PRIVATE).edit().putBoolean(SetupActivity.hdPreference(hp2),false).apply();return "HD overrides removed.";})).setNegativeButton("Cancel",null).show());col.addView(remove);Button back=new Button(this);back.setText("Return to launcher");back.setOnClickListener(v->{if(!busy)finish();});col.addView(back);ScrollView scroll=new ScrollView(this);scroll.addView(col);setContentView(scroll);refresh();}
 void refresh(){try{status.setText(HDPackInstaller.installed(root).size()+" HD textures installed for "+(hp2?"HP2":"HP1"));}catch(Exception e){status.setText(e.getMessage());}}
 interface Job{String run()throws Exception;}
 void work(Job job){if(busy)return;busy=true;install.setEnabled(false);remove.setEnabled(false);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);worker=new Thread(()->{String message;try{message=job.run();}catch(Exception e){message="HD pack operation failed: "+e.getMessage();}final String result=message;runOnUiThread(()->{busy=false;install.setEnabled(true);remove.setEnabled(true);getWindow().clearFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);status.setText(result);});},"HD pack install");worker.start();}
 protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code!=78||result!=RESULT_OK||data==null)return;List<HDPackInstaller.Source> sources=new ArrayList<>();if(data.getClipData()!=null)for(int n=0;n<data.getClipData().getItemCount();n++){final Uri uri=data.getClipData().getItemAt(n).getUri();sources.add(()->getContentResolver().openInputStream(uri));}else if(data.getData()!=null){final Uri uri=data.getData();sources.add(()->getContentResolver().openInputStream(uri));}work(()->{int count=HDPackInstaller.install(root,hp2,sources,getCacheDir(),text->runOnUiThread(()->status.setText(text)));getSharedPreferences("setup",MODE_PRIVATE).edit().putBoolean(SetupActivity.hdPreference(hp2),true).apply();return "Installed "+count+" verified HD textures for "+(hp2?"HP2":"HP1")+". Press Play in the launcher.";});}
 public void onBackPressed(){if(busy)Toast.makeText(this,"Please wait for installation to finish.",Toast.LENGTH_SHORT).show();else super.onBackPressed();}
}

